{"exp_gang_bravado","street_talk",2,"reg=gang|st=neutral,careful,hostile|world=vehicle",{1,"Do that voice again, the one you just did",2,"What voice?",1,"The big tough-- you sound like you're selling monster truck tickets",2,"Man, shut up"}},
{"exp_gang_borrowedname","street_talk",2,"reg=gang|st=neutral,careful",{1,"Where'd that name come from, anyway?",2,"Dumb thing somebody called me in school",1,"And you kept it?",2,"Not on purpose - you ever tried telling people NOT to call you something?"}},
{"ordinary_later_rule","survival",2,"reg=civilian,worker,family,outlaw|tmp=seasoned,veteran|st=neutral,careful|day=31,3650",{1,"Got a plan for next month?",2,"I'd like to be available for it",1,"Ambitious",2,"Trying not to overpromise"}},
{"s13_law_swat_callout_035","swat",3,"reg=law,swat|role=swat_lead,swat_operator|world=vehicle",{1,"State's response team is eleven men and nine of 'em live in Louisville",2,"So we've got two",3,"We've got two, a shield, and the ram out of a trunk that's sitting in Elizabethtown",1,"Then quit calling it a team - call it Sowders and Whitt and plan accordingly"}},
{"s13_swat_shield_stairs_036","swat",2,"reg=swat|role=swat_operator|world=stairs",{1,"The bunker's forty-some pounds and you hold it out off your chest going up",2,"How many stairs?",1,"Fourteen to the landing, then eight, I counted twice before we went and I'd do it again"}},
{"s13_swat_knock_notice_037","swat",2,"reg=swat|tmp=veteran|world=stairs",{1,"We still knock and announce",2,"To who?",1,"Whoever's behind it, if it's a family we don't shoot a family, and if it ain't, they heard us on the stairs"}},
{"s13_swat_gas_no_good_038","swat",2,"reg=swat|mood=grim",{1,"Gas don't work on 'em, burned four rounds of CS in that garage and they walked through it",2,"Course they did, they ain't breathing right to start with",1,"Nobody wrote that down anywhere, we found it out in a garage on a Tuesday"}},
{"s13_swat_entry_no_medic_039","swat",2,"reg=swat|role=swat_lead",{1,"We don't go in without a medic staged, that's the rule and I wrote it",2,"There is no medic staged, there's a nurse at the clinic and she's got no ride",1,"Then we don't go in",2,"There's a kid in there, Sarge",1,"Then we go in, I hate that I said the first thing out loud"}},
{"s13_sf_team_sergeant_006","team",2,"reg=elite|role=elite_operator",{1,"Team sergeant runs the team and the captain runs the map",2,"That's how it works anyway",1,"That's how it works when it's working, it's how you know when it ain't, 'cause the captain quits asking"}},
{"s13_sf_oda_split_007","team",3,"reg=elite|role=elite_operator",{1,"We're a split team, six of us",2,"Where's the other six?",1,"Bragg, Campbell, and a bass boat in Tennessee, best I know",3,"You didn't say Louisville",1,"No, I did not"}},
{"s13_sf_area_study_009","team",2,"reg=elite|mood=funny",{1,"Somebody did an area study on this county and put it in a binder",2,"In 1989?",1,"Nineteen seventy-eight, crops, churches, who runs the co-op, which family don't speak to which",2,"That last part's the only part still true"}},
{"s13_sf_brief_back_010","team",3,"reg=elite|tmp=veteran|world=road",{1,"Brief it back to me, route, actions on, what we do if the bridge is gone",2,"Before we go, agree where to meet if we get separated. Somewhere we've both actually checked",3,"Bridge gone, we go on foot, two days instead of one",1,"And who talks if we meet somebody?",2,"You do, nobody else opens their mouth"}},
{"s13_sf_isofac_011","team",2,"reg=elite|mood=funny|world=door",{1,"We used to lock a team in a room three days before a job - nobody in, nobody out",2,"And now?",1,"Now it's a school gym with the doors propped open for the air - same idea, worse doors"}},
{"s13_sf_map_1978_019","team",2,"reg=elite",{1,"This map's got a bridge on it that ain't there and a store that burnt in 1985",2,"So?",1,"So I trust the contour lines and not the print - hills don't move"}},
{"s13_sf_civilian_clothes_020","team",2,"reg=elite",{1,"Ball cap, work shirt, jeans, rifle in a feed sack",2,"Feels wrong",1,"It's supposed to, a man dressed like a soldier gets run from or begged at - both cost us a day"}},
{"s13_sf_beards_021","team",2,"reg=elite|mood=funny",{1,"A sergeant major would take one look at that face and have a stroke",2,"He ain't here, and I've got a reason, folks talk to a man with a beard, they report a haircut"}},
{"s13_sf_teaching_farmers_022","team",3,"reg=elite|role=elite_operator",{1,"Two days teaching eleven farmers to shoot a rifle they already owned",2,"How'd they do?",3,"Better than the Guard did in a week, they been shooting since they were nine",1,"They didn't need shooting taught, they needed to know when not to"}},
{"s13_sf_wont_take_over_023","team",2,"reg=elite|mood=funny",{1,"They asked us to run their camp for 'em",2,"We said no",1,"I said no, you said that's not the mission in your officer voice, which is a nasty way to say no",2,"It worked though"}},
{"s13_sf_food_local_034","team",2,"reg=elite|mood=warm",{1,"We ate at a table last night, green beans, cornbread, a tomato off the vine",2,"What'd you give 'em?",1,"Fixed the well pump, left two bottles of penicillin, and I about cried over the tomato",1,"I'd appreciate you not repeating that last part"}},
{"s13_sf_no_rescue_035","team",2,"reg=elite|mood=grim|world=cars",{1,"Folks keep asking us when the buses are coming",2,"What's the answer?",1,"No good answer, so I give 'em the real one - nobody has told me about any buses",2,"They take that alright?",1,"Better than a lie - every time, I quit being surprised by it"}},
{"s13_sf_merc_together_051","team",3,"reg=elite|role=elite_operator,mercenary|world=fence,road",{1,"We're not working for you and you're not working for us",2,"Agreed",1,"But that fence has got one gate and one road - so who's got the road?",2,"You take the road, I take the gate, and after, neither of us says the other was in charge",3,"Somebody write that down"}},
{"s13_delta_sleep_053","team",2,"reg=elite|mood=funny",{1,"You sleep four hours?",2,"Two - twice",1,"Call that four hours? It's two twos",2,"It's been two twos for nine days and the arithmetic's about to get a vote"}},
{"s13_sf_church_deal_057","team",2,"reg=elite|mood=warm",{1,"Preacher wants to know what we want for fixing the well pump",2,"Nothing",1,"He won't take nothing, he'll worry at it a week",2,"Then tell him a hot meal and the name of everybody in that building, wrote down - he'll feel square"}},
{"exp_swat_unasked","teamwork",2,"reg=swat|st=neutral,careful",{1,"Didn't have to ask that time",2,"You already yelled at me about it twice",1,"Three times",2,"Well, there you go, third one stuck"}},
{"exp_elite_assumption","teamwork",2,"reg=elite|st=neutral,careful",{1,"You know that or you're guessing?",2,"Guessing",1,"Okay, say that first",2,"Fair"}},
{"exp_elite_plain_words","teamwork",2,"reg=elite|st=neutral,careful",{1,"You want the whole thing?",2,"Short version, what you actually saw",1,"Not much, that's the problem",2,"Start there, then"}},
{"ordinary_prison_clock","time",2,"reg=prison|st=neutral,careful|world=door",{1,"I still wake up before count",2,"Nobody's counting you here",1,"Tell that to whatever's inside my head",2,"Takes more than an open door to get some things out"}},
{"exp_swat_repetition","training_memory",2,"reg=swat|st=neutral,careful",{1,"Used to hate running that drill again, one more time, one more time",2,"Till somebody got sloppy, then another ten",1,"Yeah, usually me",2,"Usually you"}},
{"exp_swat_gloves","training_memory",2,"reg=swat|st=neutral,careful",{1,"Remember the gloves with L and R written on them?",2,"Backwards - yeah, kept wondering why they felt wrong",1,"You knew all morning and didn't say shit",2,"Wanted to see how long it'd take"}},
{"exp_military_inspection","training_memory",2,"reg=military|st=neutral,careful",{1,"I cleaned UNDER the damn chair - for inspection",2,"And?",1,"He wiped the seat - dust everywhere, I'd forgotten the fucking seat",2,"Oh, he must've loved you"}},
{"exp_military_bootsize","training_memory",2,"reg=military|st=neutral,careful|world=window",{1,"Supply asked if my feet were different sizes",2,"Were they?",1,"Boots were, nine and eleven - told me to wear thicker socks",2,"Just on the one foot?",1,"I asked that, guy shut the window on me"}},
{"s13_law_uniform_shirt_016","uniform",1,"reg=law|mood=sad",{1,"I still iron the shirt, both sleeves, the collar, the crease down the pocket",1,"Ain't a soul left to inspect it, there's no inspection anymore",1,"It's just I don't know what I am with it off"}},
{"s13_ksp_gray_hat_005","uniform",2,"reg=law|role=law_trooper",{1,"You still wearing the hat?",2,"Every stop, man sees the gray and the hat and his hands go on the wheel unasked - worth the sweat"}},
{"s13_ksp_hat_in_window_029","uniform",2,"reg=law|tmp=veteran|world=vehicle,window",{1,"Put the hat in the back window when you sleep in the car",2,"Why?",1,"So whoever walks up sees the hat before they see a man asleep - sometimes that's the difference"}},
{"s13_ksp_post_flag_043","uniform",2,"reg=law|mood=sad",{1,"Somebody took the flag down at the post and folded it right - corners square, the whole thing",2,"Who?",1,"Don't know, it was on the counter with a note that said sorry - that's all it said - sorry"}},
{"s13_mp_brassard_033","uniform",2,"reg=military|tmp=veteran",{1,"That armband's all that makes you different from any other man out here with a rifle",2,"It's a piece of cloth",1,"Piece of cloth that lets a fella walk up and complain, so I wear it clean"}},
{"s13_mp_class_a_gate_041","uniform",2,"reg=military|mood=funny",{1,"Loveless is out there in a pressed uniform with a shine on his boots",2,"In this heat?",1,"Says the gate's the first thing anybody sees of the United States Army - he ain't wrong, he's also going to faint"}},
{"exp_law_hat_rain","uniforms",2,"reg=law|st=neutral,careful,friendly",{1,"I used to put my hat under my shirt when it rained",2,"I saw you do it - looked ridiculous",1,"Replacement came out of my pay, I'd look ridiculous for thirty bucks",2,"You'd do it for less, I've seen that too"}},
